                // Circuit may already be gone during prerendering or navigation.
            }
        }

        _dotNetRef?.Dispose();
    }
}

let state = null;

export function initialize(container, dotNetRef, timeoutSeconds) {
    const timeoutMs = timeoutSeconds * 1000;
    let isIdle = false;
    let timerId = null;

    function resetTimer() {
        clearTimeout(timerId);
        timerId = setTimeout(onTimeout, timeoutMs);
    }

    function onTimeout() {
        if (!isIdle) {
            isIdle = true;
            dotNetRef.invokeMethodAsync("NotifyIdle");
        }
    }

    function onActivity() {
        if (isIdle) {
            isIdle = false;
            dotNetRef.invokeMethodAsync("NotifyActive");
        }
        resetTimer();
    }

    const events = ["mousemove", "keydown", "click", "scroll"];
    events.forEach(evt => container.addEventListener(evt, onActivity, { passive: true }));

    resetTimer();

    state = {
        container,
        events,
        onActivity,
        timerId: () => timerId,
        clearTimer: () => clearTimeout(timerId),
    };
}

export function dispose() {
    if (!state) return;

    state.clearTimer();
    state.events.forEach(evt =>
        state.container.removeEventListener(evt, state.onActivity)
    );
    state = null;
}

